export const legacyMessageBindingTrigger = "CREATE TRIGGER messages_bind_agents AFTER INSERT ON messages BEGIN\n      UPDATE messages SET from_actor = COALESCE(NULLIF(COALESCE((SELECT CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END\n      FROM agents a WHERE (length(CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END) <= 128 AND (length(a.tag) BETWEEN 1 AND 64 AND a.tag NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.tag,1,1) GLOB '[A-Za-z0-9]' AND lower(a.tag) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.tag) NOT LIKE 'root%') AND (COALESCE(a.project,'') = '' OR (length(a.project) BETWEEN 1 AND 64 AND a.project NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.project,1,1) GLOB '[A-Za-z0-9]' AND lower(a.project) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.project) NOT LIKE 'root%'))) AND\n      (CASE WHEN instr(NEW.from_actor,':') = 0 THEN a.tag ELSE a.project || ':' || a.tag END) = NEW.from_actor\n      AND (instr(NEW.from_actor,':') > 0 OR (SELECT COUNT(*) FROM agents WHERE tag = NEW.from_actor) = 1)\n      \n      LIMIT 1), ''),''), NEW.from_actor), to_actor = COALESCE(NULLIF(COALESCE((SELECT CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END\n      FROM agents a WHERE (length(CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END) <= 128 AND (length(a.tag) BETWEEN 1 AND 64 AND a.tag NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.tag,1,1) GLOB '[A-Za-z0-9]' AND lower(a.tag) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.tag) NOT LIKE 'root%') AND (COALESCE(a.project,'') = '' OR (length(a.project) BETWEEN 1 AND 64 AND a.project NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.project,1,1) GLOB '[A-Za-z0-9]' AND lower(a.project) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.project) NOT LIKE 'root%'))) AND\n      (CASE WHEN instr(NEW.to_actor,':') = 0 THEN a.tag ELSE a.project || ':' || a.tag END) = NEW.to_actor\n      AND (instr(NEW.to_actor,':') > 0 OR (SELECT COUNT(*) FROM agents WHERE tag = NEW.to_actor) = 1)\n      \n      LIMIT 1), ''),''), NEW.to_actor),\n        registry_unbound_from = CASE WHEN instr(NEW.from_actor,':') = 0 AND (length(NEW.from_actor) BETWEEN 1 AND 64 AND NEW.from_actor NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(NEW.from_actor,1,1) GLOB '[A-Za-z0-9]' AND lower(NEW.from_actor) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(NEW.from_actor) NOT LIKE 'root%') AND COALESCE((SELECT CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END\n      FROM agents a WHERE (length(CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END) <= 128 AND (length(a.tag) BETWEEN 1 AND 64 AND a.tag NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.tag,1,1) GLOB '[A-Za-z0-9]' AND lower(a.tag) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.tag) NOT LIKE 'root%') AND (COALESCE(a.project,'') = '' OR (length(a.project) BETWEEN 1 AND 64 AND a.project NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.project,1,1) GLOB '[A-Za-z0-9]' AND lower(a.project) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.project) NOT LIKE 'root%'))) AND\n      (CASE WHEN instr(NEW.from_actor,':') = 0 THEN a.tag ELSE a.project || ':' || a.tag END) = NEW.from_actor\n      AND (instr(NEW.from_actor,':') > 0 OR (SELECT COUNT(*) FROM agents WHERE tag = NEW.from_actor) = 1)\n      \n      LIMIT 1), '') = '' THEN 1 ELSE NEW.registry_unbound_from END,\n        registry_unbound_to = CASE WHEN instr(NEW.to_actor,':') = 0 AND (length(NEW.to_actor) BETWEEN 1 AND 64 AND NEW.to_actor NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(NEW.to_actor,1,1) GLOB '[A-Za-z0-9]' AND lower(NEW.to_actor) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(NEW.to_actor) NOT LIKE 'root%') AND COALESCE((SELECT CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END\n      FROM agents a WHERE (length(CASE WHEN COALESCE(a.project,'') = '' THEN a.tag ELSE a.project || ':' || a.tag END) <= 128 AND (length(a.tag) BETWEEN 1 AND 64 AND a.tag NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.tag,1,1) GLOB '[A-Za-z0-9]' AND lower(a.tag) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.tag) NOT LIKE 'root%') AND (COALESCE(a.project,'') = '' OR (length(a.project) BETWEEN 1 AND 64 AND a.project NOT GLOB '*[^A-Za-z0-9._-]*'\n    AND substr(a.project,1,1) GLOB '[A-Za-z0-9]' AND lower(a.project) NOT IN\n    ('human','role','machine','routing','routing-client','job','schedule','admin','root','principal','system','hub')\n    AND lower(a.project) NOT LIKE 'root%'))) AND\n      (CASE WHEN instr(NEW.to_actor,':') = 0 THEN a.tag ELSE a.project || ':' || a.tag END) = NEW.to_actor\n      AND (instr(NEW.to_actor,':') > 0 OR (SELECT COUNT(*) FROM agents WHERE tag = NEW.to_actor) = 1)\n      \n      LIMIT 1), '') = '' THEN 1 ELSE NEW.registry_unbound_to END\n        WHERE id = NEW.id;\n      END";
